CREATE TABLE IF NOT EXISTS app_users (id TEXT PRIMARY KEY, first_name TEXT NOT NULL, last_name TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'Device Systems Specialist', permissions TEXT NOT NULL DEFAULT '{}', weekly_schedule TEXT NOT NULL DEFAULT '{}', trained_devices TEXT NOT NULL DEFAULT '[]', is_new_hire INTEGER NOT NULL DEFAULT 0, dashboard_layout TEXT NOT NULL DEFAULT 'lanes', pin_hash TEXT NOT NULL, is_active INTEGER NOT NULL DEFAULT 1, is_logged_in INTEGER NOT NULL DEFAULT 0, last_login_at TEXT, last_logout_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS app_users_name_unique ON app_users(lower(first_name), lower(last_name));
CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS trial_files (id TEXT PRIMARY KEY, last_name TEXT NOT NULL, first_name TEXT NOT NULL, device TEXT NOT NULL, device_number TEXT NOT NULL DEFAULT '', gipod_code TEXT NOT NULL DEFAULT '', new_gipod_code TEXT NOT NULL DEFAULT '', camera_number TEXT NOT NULL DEFAULT '', camera_number_2 TEXT NOT NULL DEFAULT '', camera_number_3 TEXT NOT NULL DEFAULT '', camera_number_4 TEXT NOT NULL DEFAULT '', loan_type TEXT NOT NULL DEFAULT '', queue_date TEXT, expiration_date TEXT, vocabulary TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', priority TEXT NOT NULL DEFAULT 'Normal', status TEXT NOT NULL DEFAULT 'Ready for Pre-Prep', lane TEXT NOT NULL DEFAULT 'Daily Queue', crm_link TEXT NOT NULL DEFAULT '', prepper TEXT NOT NULL DEFAULT '', prepped_by TEXT NOT NULL DEFAULT '', qa_by TEXT NOT NULL DEFAULT '', prepped_by_user_id TEXT, qa_by_user_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS gipod_codes (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE COLLATE NOCASE, used_on TEXT NOT NULL DEFAULT '', used_date TEXT, note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS gipod_code_requests (id TEXT PRIMARY KEY, file_id TEXT NOT NULL REFERENCES trial_files(id) ON DELETE CASCADE, requester_user_id TEXT, requester_name TEXT NOT NULL DEFAULT '', first_name TEXT NOT NULL DEFAULT '', last_name TEXT NOT NULL DEFAULT '', device TEXT NOT NULL DEFAULT '', crm_number TEXT NOT NULL DEFAULT '', reason TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'pending', gipod_code TEXT NOT NULL DEFAULT '', resolved_by_user_id TEXT, requested_at TEXT NOT NULL, resolved_at TEXT, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS device_requests (id TEXT PRIMARY KEY, crm_link TEXT NOT NULL DEFAULT '', device_number TEXT NOT NULL DEFAULT '', internal_serial_number TEXT NOT NULL DEFAULT '', request_type TEXT NOT NULL, apps_wanted TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', requester_user_id TEXT, requester_name TEXT NOT NULL DEFAULT '', requester_role TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'pending', claimed_by_user_id TEXT, claimed_by_name TEXT NOT NULL DEFAULT '', completed_by_user_id TEXT, completed_by_name TEXT NOT NULL DEFAULT '', requested_at TEXT NOT NULL, claimed_at TEXT, completed_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS app_file_logs (id TEXT PRIMARY KEY, file_id TEXT NOT NULL REFERENCES trial_files(id) ON DELETE CASCADE, actor_user_id TEXT, actor_name TEXT NOT NULL DEFAULT '', action TEXT NOT NULL, field_name TEXT NOT NULL DEFAULT '', old_value TEXT NOT NULL DEFAULT '', new_value TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS app_user_activity (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, file_id TEXT NOT NULL REFERENCES trial_files(id) ON DELETE CASCADE, action TEXT NOT NULL, activity_date TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS app_shipment_activity (id TEXT PRIMARY KEY, file_id TEXT NOT NULL UNIQUE, first_name TEXT NOT NULL DEFAULT '', last_name TEXT NOT NULL DEFAULT '', loan_type TEXT NOT NULL DEFAULT '', device TEXT NOT NULL DEFAULT '', lane TEXT NOT NULL DEFAULT '', shipped_by_user_id TEXT, shipped_date TEXT NOT NULL, shipped_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS app_eod_cleanups (id TEXT PRIMARY KEY, cleanup_date TEXT NOT NULL, cleaned_by_user_id TEXT, file_count INTEGER NOT NULL DEFAULT 0, loan_totals TEXT NOT NULL DEFAULT '{}', device_totals TEXT NOT NULL DEFAULT '{}', accessory_totals TEXT NOT NULL DEFAULT '{}', files TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS coordinator_auto_queue (id TEXT PRIMARY KEY, user_id TEXT NOT NULL UNIQUE, entered_at TEXT NOT NULL);
